export const FOOD_CATEGORIES = ["Bevande","Carboidrati","Grassi","Proteine","Snack","Verdure"];
// La ricerca vera e' web/food-search.js (NurvanFoodSearch): pertinenza, uso
// recente, limite. Questa resta per chi carica il catalogo senza la pagina.
export function searchFoodCatalog(query, limit = 8) {
  if (typeof self !== 'undefined' && self.NurvanFoodSearch) return self.NurvanFoodSearch.rank(FOOD_CATALOG, query, { limit: limit });
  const q = String(query || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  if (!q) return [];
  return FOOD_CATALOG.filter((f) => f.name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').includes(q)).slice(0, limit);
}
export default { FOOD_CATALOG, FOOD_CATEGORIES, searchFoodCatalog };
